END   { END_TOKEN }

%start Program

Program  -> ProgramBlock EOF;

ProgramBlock -> var DeclarationList;

DeclarationList -> Declaration DeclarationList | /* empty */;

Declaration -> ID ':' Type;

ID_TOKEN    = [a-zA-Z_][a-zA-Z0-9_]*;
INTEGER_TOKEN = [0-9]+;
ASSIGN_TOKEN = '=';
